/* Original Dojo quest actor and kite meshes; static bind poses. */
#define QUEST_ID35 0x7fe0u
static void quest_upload35(const U8 *data){for(int m=0;m<Q35_TEX;m++){uploadrect19(768,80+m,256,1,data+m*512);uploadrect19(832+(m%6)*32,384+(m/6)*64,32,64,data+Q35_TEX*512+m*4096);}gp(0x01000000);idle();}
static void quest_packet35(const Packet*q,int m){int col=m%6,row=m/6;gp(0xe2000000u|24|(24<<5)|((col%4)*8<<10)|((2+row)*8<<15));gp(0x24808080);gp(packetxy(q,0));gp(q->uv[0]|((48|((80+m)<<6))<<16));gp(packetxy(q,1));gp(q->uv[1]|(((13+2*(col/4))|16|128)<<16));gp(packetxy(q,2));gp(q->uv[2]);}
static void quest_mesh35(int id,int x,int y,int z,int h,int cx,int cy,int cz,int sn,int cs){const QuestModel35 *m=qmodels35+id;static Point pts[Q35_MAXV];int a=sine[h&63],b=sine[(h+16)&63];for(int j=0;j<m->nv;j++){int xx=m->v[j][0],yy=m->v[j][1],zz=m->v[j][2];pts[j]=transform(x+((b*xx+a*zz)>>12),y+yy,z+((b*zz-a*xx)>>12),cx,cy,cz,sn,cs);}for(int f=0;f<m->nf;f++){Point v[3];const QuestFace35*t=m->f+f;for(int j=0;j<3;j++){v[j]=pts[t->idx[j]];v[j].u=t->uv[j*2];v[j].v=t->uv[j*2+1];}worldtri(v[0],v[1],v[2],QUEST_ID35+t->mat);}}
static void renderquest35(Player18*p,int cx,int cy,int cz,int sn,int cs){for(int j=0;j<cache.count;j++){int k=cache.active[j];const U32*m=cache.meta[k];const U8*t=cache.bytes[k]+64+m[1]*36+m[2]*24;for(U32 n=0;n<m[3];n++,t+=16){if(s18(t+6)!=4)continue;U32 id=rd18(t+12);int x=s18(t)+(int)m[4],y=s18(t+2)+(int)m[5],z=s18(t+4)+(int)m[6];if(ab(x-p->x)>1400||ab(z-p->z)>1400)continue;for(int i=0;i<3;i++){if(id==qnpc34[i])quest_mesh35(i,x,y,z,heading31(p->x-x,p->z-z,sine),cx,cy,cz,sn,cs);}}}
 for(int i=0;i<3;i++)if(quest34.stage[i]<Q34_RETURNED){int v[3];if(quest34.stage[i]==Q34_IDLE){for(int j=0;j<3;j++)v[j]=qidle35[i][j];}else quest_pos34(&quest34,i,v);if(ab(v[0]-p->x)<=1400&&ab(v[2]-p->z)<=1400)quest_mesh35(3,v[0],v[1],v[2],0,cx,cy,cz,sn,cs);}}
